{
  "requirements": [
    {
      "text": "The system shall enable searching for books with a response time of under 2 seconds for 95% of queries.",
      "kaos_level": "tactical",
      "rationale": "Fast search response times enhance user experience and system efficiency."
    },
    {
      "text": "The system shall allow up to 10 simultaneous book borrow operations per member to optimize resource utilization.",
      "kaos_level": "operational",
      "rationale": "Setting a borrowing limit ensures efficient management of library resources."
    },
    {
      "text": "The system shall track book availability and update the status in real-time to ensure accurate information.",
      "kaos_level": "tactical",
      "rationale": "Real-time tracking minimizes confusion and improves operational efficiency."
    },
    {
      "text": "The system shall process book returns within 1 second to maintain high throughput.",
      "kaos_level": "operational",
      "rationale": "Quick processing of returns maximizes system throughput and member satisfaction."
    },
    {
      "text": "The system shall send overdue notifications to members within 24 hours of the due date to ensure accountability.",
      "kaos_level": "operational",
      "rationale": "Timely notifications improve resource management and member compliance."
    },
    {
      "text": "The system shall enable librarians to add or remove books with a latency of less than 3 seconds per operation.",
      "kaos_level": "tactical",
      "rationale": "Minimizing latency in administrative tasks enhances overall system performance."
    },
    {
      "text": "The system shall maintain an uptime of 99.5% to ensure consistent availability for users.",
      "kaos_level": "strategic",
      "rationale": "High availability is critical for maintaining user trust and operational efficiency."
    }
  ]
}
